 if(!immediate){formModal('بازگرداندن به تعهدات برنامه‌ریزی‌نشده',html,execute,{topActions:true});return}
 returningAllocations=true;try{applyReturnResult(await execute(state.revision))}catch(e){formModal('بازگرداندن به تعهدات برنامه‌ریزی‌نشده',html,execute,{topActions:true});showValidationError(e)}finally{returningAllocations=false}
