function editGroupAllocation(blockIds,expertId=null,week=null){
 if(blockIds.length<2||blockIds.length>50){shell.status('برای تخصیص گروهی، بین ۲ تا ۵۰ بلوک انتخاب کنید.');return}
 const blocks=blockIds.map(id=>state.blocks.find(b=>b.id===id));
 if(blocks.some(b=>!b)||blocks.some(b=>state.allocations.some(a=>a.blockId===b.id))){shell.status('بلوک دارای تخصیص یا نامعتبر را جداگانه ویرایش کنید.');return}
 const kinds=new Set(blocks.map(b=>state.obligations[b.obligationId]?.kind));
 if(kinds.size!==1||![...kinds][0]){shell.status('بلوک‌های استقرار و کانورت را جداگانه انتخاب کنید.');return}
 const kind=[...kinds][0],experts=state.experts.filter(e=>e.active&&e.kind===kind);
 if(expertId&&!experts.some(e=>e.id===expertId)){shell.status('نوع بک‌لاگ باید با گروه کارشناس یکسان باشد.');return}
 if(!experts.length){shell.status('کارشناس فعال در این گروه وجود ندارد.');return}
 const start=week||[...blocks.map(b=>state.obligations[b.obligationId]?.week).filter(Boolean)].sort()[0]||startWeek(state.today);
 formModal('تخصیص گروهی بلوک‌ها',`<p>${num(blocks.length)} بلوک ${typeName(kind)} انتخاب شده است؛ از روز آغاز، به ترتیب روزهای کاری تخصیص می‌یابند.</p><div class="dp-form-grid">${select('f-expert','کارشناس',experts.map(e=>[e.id,e.name]),expertId||'')}${dateField('f-group-week','روز آغاز',start>=startWeek(state.today)?start:startWeek(state.today))}</div><p class="ui-muted">اگر روزهای این هفته کافی نباشد، برنامه در هفتهٔ بعد ادامه پیدا می‌کند. موارد نامعتبر همگی با هم رد می‌شوند.</p>`,async revision=>{
  const chosenExpert=fieldValue('f-expert'),chosenStart=fieldValue('f-group-week');if(!chosenExpert||!experts.some(e=>e.id===chosenExpert))throw Error('کارشناس هم‌گروه را انتخاب کنید.');if(!chosenStart||!span(chosenStart,chosenStart).length)throw Error('روز آغاز را انتخاب کنید.');
  let cursor=chosenStart,items=blocks.map(b=>{let left=b.units,days=[];while(left>0){if(cursor<startWeek(state.today))throw Error('هفتهٔ گذشته قابل تخصیص نیست.');const weekday=new Date(cursor).getUTCDay(),ordinary=kind==='Converter'||![4,5].includes(weekday);if(ordinary){const units=Math.min(left,2);days.push({date:cursor,units});left-=units}cursor=add(cursor,1);if(days.length>365)throw Error('بازهٔ تخصیص بیش از حد طولانی است.')}return {blockId:b.id,expertId:chosenExpert,days,note:''}});
  const result=await command('allocate-group',{items},revision);selectedBlocks.clear();return result
 },{topActions:true})
}

