function approve(ids){if(!ids.length){shell.status('ابتدا تخصیص‌ها را انتخاب کنید.');return}const originalRows=structuredClone(ids.map(id=>state.allocations.find(a=>a.id===id)));const summary=[...new Set(ids.map(id=>state.allocations.find(a=>a.id===id)?.obligationId))].filter(Boolean).map(id=>{const o=state.obligations[id],c=state.coverage[id];return '<li><strong>'+esc(o.customer||o.project)+'</strong> · '+esc(o.title)+'<br>وضعیت CRM: '+esc(statusName(o.status))+' · نیاز: '+num((c.required||0)/2)+' روز · برنامه: '+num(c.assigned/2)+' روز · کسری: '+num((c.missing||0)/2)+' روز</li>'}).join('');formModal('قطعی‌سازی برنامه',`<p>${num(ids.length)} تخصیص انتخاب‌شده در همین سامانه قطعی می‌شود؛ وضعیت CRM تغییر نمی‌کند. پوشش کامل تعهد و وضعیت مجاز CRM الزامی است.</p><p class="ui-muted">کادر قرمز یعنی تخصیص قطعی؛ کادر معمولی یعنی پیشنهادی. در این اقدام فقط تخصیص‌های انتخاب‌شده قطعی می‌شوند. اگر یک مورد معتبر نباشد، هیچ موردی قطعی نمی‌شود.</p><ul class="dp-approval-summary">${summary}</ul>${warningFields()}`,revision=>saveGroupMove({ids,...warningData()},originalRows,revision,'approve'))}
async function saveGroupMove(data,originalRows,revision,action='move-group'){
 try{return await command(action,data,revision)}catch(error){
  if(error.status!==409||error.message!=='برنامه هم‌زمان تغییر کرده؛ دوباره بارگذاری کنید.')throw error;
  const latest=await api('state/compact');
  if(originalRows.some(before=>JSON.stringify(before)!==JSON.stringify(latest.allocations.find(a=>a.id===before.id))))throw Error('یکی از تخصیص‌های انتخاب‌شده از زمان بازشدن فرم تغییر کرده یا حذف شده است. برای جلوگیری از بازنویسی، فرم را ببندید و برنامه را تازه کنید.');
  state=latest;dialog.dataset.revision=String(latest.revision);
  return command(action,data,latest.revision)
 }
}
