function toggleExpert(id){if(!info.manager)return;const e=state.experts.find(e=>e.id===id);if(!e)return;formModal(e.active?'برداشتن کارشناس از فهرست فعال':'فعال‌کردن دوبارهٔ کارشناس',`<p>${esc(e.name)} ${e.active?'از فهرست کارشناسان فعال برداشته شود؟ تخصیص‌های ثبت‌شده و تاریخچه حفظ می‌شوند.':'دوباره به فهرست کارشناسان فعال برگردد؟'}</p>`,revision=>command('expert',{...e,active:!e.active},revision))}
function editAbsence(id){const a=state.absences.find(a=>a.id===id);formModal('عدم دسترسی کارشناس','<p class="ui-muted">برای استقرار یا کانورت واقعی، از بلوکِ تعهد CRM استفاده کنید.</p>'+select('f-expert','کارشناس',state.experts.filter(e=>e.active||e.id===a?.expertId).map(e=>[e.id,e.name]),a?.expertId)+select('f-type','نوع',['مرخصی','مأموریت غیرمرتبط','آموزش داخلی','فعالیت داخلی','سایر عدم دسترسی'].map(x=>[x,x]),a?.type||'مرخصی')+`<div class="dp-form-grid">${dateField('f-from','شروع',a?.from||state.today)}${dateField('f-to','پایان',a?.to||state.today)}</div>`+input('f-note','یادداشت',a?.note||'','maxlength="2000"')+(a?btn('حذف عدم دسترسی','id="dp-delete-absence"'):''),revision=>command('absence',{id:a?.id,expertId:fieldValue('f-expert'),type:fieldValue('f-type'),from:fieldValue('f-from'),to:fieldValue('f-to'),note:fieldValue('f-note')},revision));$('dp-delete-absence')?.addEventListener('click',()=>formModal('حذف عدم دسترسی','<p>عدم دسترسی انتخاب‌شده حذف شود؟</p>',revision=>command('delete-absence',{id},revision)))}
function editSwitch(id){const o=state.obligations[id],p=state.plans[o.projectId]||{};formModal('پلن و سوئیچ '+o.project,`<p class="ui-muted">مرجع سینک نهایی: ${p.reference?fullDate(p.reference):'تاریخ مرجع نامشخص'}</p><div class="dp-form-grid">${dateField('f-switch','سوئیچ دستی؛ خالی یعنی مرجع',p.date||'')}${dateField('f-completion','پایان پیش‌بینی‌شدهٔ کانورت',p.completion||'')}</div>`+select('f-stage','مرحله در صورت نامعلوم‌بودن تاریخ',[['unknown','نامشخص'],['before','قبل از سوئیچ'],['after','بعد از سوئیچ']],p.stage||'unknown')+input('f-note','یادداشت',p.note||'')+input('f-color','رنگ مشتری پس از سوئیچ',state.colors[o.customerId]||'#e4f1eb','type="color"'),async revision=>{return command('switch',{projectId:o.projectId,date:fieldValue('f-switch')||null,completion:fieldValue('f-completion')||null,stage:fieldValue('f-stage'),note:fieldValue('f-note'),color:fieldValue('f-color')},revision)})}
function weekDetails(w){modal('نمای روزانهٔ '+fmt(w),`<div class="ui-row" style="margin-bottom:12px">${info.manager&&w>=startWeek(state.today)?btn('قطعی‌سازی پیشنهادهای این هفته','id="dp-approve-week"'):''}</div>`+dayMatrix(state,w));$('dp-approve-week')?.addEventListener('click',()=>approve(state.allocations.filter(a=>a.status==='proposed'&&a.days.some(d=>startWeek(d.date)===w)).map(a=>a.id)))}
function paintSettings(){
 const test=checking?'در حال تست اتصال…':connectionCheck?.state==='connected'?'اتصال تأیید شد':connectionCheck?.message||(info?.crmConnected?'حساب سازمانی ثبت شده':'حساب سازمانی متصل نیست');
 $('dp-connection-state').textContent=test;$('dp-connection-state').dataset.state=connectionCheck?.state||'setup';$('dp-connection-identity').textContent=connectionCheck?.identity||info?.crmIdentity||'';$('dp-connection-checked').textContent=connectionCheck?.checkedAt?'آخرین تست: '+instant(connectionCheck.checkedAt):'تست اتصال در این ابزار انجام نشده است.';$('dp-test-connection').disabled=checking||!info?.crmConnected;
}
const menus=bindHeaderMenus([[$('cs-settings'),$('cs-settings-dialog')]],{onOpen:()=>{paintSettings();api('info').then(v=>{info=v;paintSettings()}).catch(e=>shell.status(e.message))}})
$('dp-test-connection').onclick=async()=>{if(checking)return;checking=true;paintSettings();$('dp-connection-result').textContent='';try{connectionCheck=await api('connection/check',{});$('dp-connection-result').textContent='اتصال CRM با حساب '+connectionCheck.identity+' تأیید شد.'}catch(e){connectionCheck={state:'unavailable',message:e.message};$('dp-connection-result').textContent=e.message}finally{checking=false;paintSettings()}}
$('dp-open-settings').onclick=()=>{menus.close();view='settings';$('cs-page-title').textContent='تنظیمات برنامه‌ریزی';$('cs-breadcrumb-page').textContent='تنظیمات';render();if(!viewCatalogLoaded)void loadViewCatalog()}
initializeChangePassword(async(url,options={})=>{const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...options.headers}}),result=await response.json();if(!response.ok)throw Error(result.error||'درخواست انجام نشد.');return result})
const changePassword=$('change-password').onclick;$('change-password').onclick=()=>{menus.close();changePassword();const panel=document.querySelector('dialog.account-dialog');if(panel){panel.classList.add('ui-dialog');panel.querySelectorAll('input').forEach(input=>input.classList.add('ui-input'));panel.querySelectorAll('button:not(.password-toggle)').forEach(button=>button.classList.add('ui-button'));panel.querySelector('[type=submit]')?.classList.add('ui-button--primary')}}
async function sync(mode='manual'){if(busy)return;busy=true;$('dp-sync').disabled=true;try{const job=await api('sync',{mode});if(job.state==='disabled'){busy=false;$('dp-sync').disabled=false;return}jobId=job.id;sessionStorage.setItem('deploymentplan-job',jobId);await pollJob()}catch(e){busy=false;$('dp-sync').disabled=false;shell.status(e.message)}}
async function pollJob(){if(!jobId)return;try{const job=await api('job?id='+encodeURIComponent(jobId));shell.status(job.message);if(job.state==='running'){setTimeout(pollJob,1500);return}jobId=null;sessionStorage.removeItem('deploymentplan-job');busy=false;$('dp-sync').disabled=false;if(job.state==='success')await reload()}catch(e){jobId=null;busy=false;sessionStorage.removeItem('deploymentplan-job');$('dp-sync').disabled=false;shell.status(e.message)}}
$('dp-sync').onclick=()=>sync();$('dp-reload').onclick=()=>reload().catch(e=>shell.status(e.message))
window.addEventListener('combine:navigate',e=>{view=e.detail.id;shell.status('');if(stateNeedsRefresh&&view!=='matrix'||view==='audit'&&!state.audit?.length)void reload().catch(error=>shell.status(error.message));else render()})
window.addEventListener('hashchange',()=>{if(state&&location.hash==='#decisions'){importMode='decision';shell.navigate('imports')}})
window.addEventListener('offline',()=>shell.status('ارتباط قطع است؛ برنامهٔ نمایش‌داده‌شده حفظ شده است.'))
try{info=await api('info');$('dp-person').textContent=info.name;shell.setIdentity(info);shell.setVersion(info.version);await reload();shell.start();if(location.hash==='#decisions'){importMode='decision';shell.navigate('imports')}if(location.hash==='#settings'){view='settings';$('cs-page-title').textContent='تنظیمات برنامه‌ریزی';$('cs-breadcrumb-page').textContent='تنظیمات';render();if(!viewCatalogLoaded)void loadViewCatalog()}if(!info.crmConnected)shell.status('برای دریافت تعهدات، حساب سازمانی CRM را از تنظیمات مشترک متصل کنید.');jobId=sessionStorage.getItem('deploymentplan-job');if(jobId){busy=true;$('dp-sync').disabled=true;pollJob()}else if(state.settings.syncOnEntry&&info.crmConnected)sync('entry')}catch(e){shell.status(e.message);$('tool-content').innerHTML='<section class="ui-card dp-empty">برنامه دریافت نشد؛ از «تازه‌سازی نمایش» دوباره تلاش کنید.</section>'}
